### 1. 推荐：对该 API 上游使用 HTTP/1.1

在 Nginx 里对转发到 web-api 的 `upstream` 使用 **HTTP/1.1**，避免 HTTP/2 带来的问题。

```nginx
upstream web_api {
    server 127.0.0.1:9508;  # 或你的 Hyperf 服务地址
    keepalive 32;
}

server {
    listen 443 ssl http2;
    server_name ht-sq01-xxx.chunquqiulai.top;

    location /api/ {
        proxy_pass http://web_api/ht/v1/;   # 根据实际重写规则调整
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # 适当加大缓冲，避免大响应被截断
        proxy_buffer_size 128k;
        proxy_buffers 4 256k;
        proxy_busy_buffers_size 256k;
        proxy_temp_file_write_size 256k;
    }
}
```

要点：

- 对**客户端**仍可用 `listen 443 ssl http2`（浏览器到 Nginx 仍是 HTTP/2）。
- Nginx 到后端用 `proxy_http_version 1.1`，即**上游使用 HTTP/1.1**，避免与后端/Swoole 在 HTTP/2 上的兼容问题。
- `proxy_buffer_size` / `proxy_buffers` 适当调大，保证大响应能完整缓冲再发给客户端。

### 2. 若必须全程 HTTP/2：加大代理缓冲

若不能改上游为 HTTP/1.1，可先尝试只加大缓冲：

```nginx
location /api/ {
    proxy_pass http://web_api/ht/v1/;
    proxy_http_version 1.1;
    proxy_set_header Connection "";
    # 大响应需要更大缓冲
    proxy_buffer_size 128k;
    proxy_buffers 8 256k;
    proxy_busy_buffers_size 256k;
    proxy_temp_file_write_size 256k;
    proxy_read_timeout 60s;
    proxy_send_timeout 60s;
}
```

### Task 3: 创建 doc-paths.js 路径辅助模块

**File**: `scripts/rag/lib/doc-paths.js`（新建）

此模块定义 RAG 索引的源文件分类规则，适配 PHP/Hyperf 项目结构。

**After**:
```javascript
'use strict';

const path = require('path');

const REPO_ROOT = path.resolve(__dirname, '..', '..', '..');

const EXCLUDED_DIRS = new Set([
  'node_modules',
  'vendor',
  'ai-pipeline',
  'archive',
  'deprecated',
  '.git',
]);

const SOURCE_GLOBS = [
  {
    root: '.cursor/rules',
    layer: 'rules',
    exts: ['.mdc'],
  },
  {
    root: 'knowledge',
    layer: 'business',
    exts: ['.md', '.yaml', '.yml'],
  },
  {
    root: 'docs',
    layer: 'business',
    exts: ['.md'],
  },
  {
    root: 'memory',
    layer: 'business',
    exts: ['.md'],
  },
];

function shouldExcludeDir(dirName) {
  return EXCLUDED_DIRS.has(dirName);
}

function getLayerForFile(relPath) {
  for (const source of SOURCE_GLOBS) {
    if (relPath.startsWith(source.root + '/') || relPath.startsWith(source.root + path.sep)) {
      const ext = path.extname(relPath).toLowerCase();
      if (source.exts.includes(ext)) {
        return source.layer;
      }
    }
  }
  return null;
}

function inferModule(relPath) {
  if (relPath.startsWith('.cursor/rules')) return 'global-rules';
  if (relPath.startsWith('memory/')) return 'memory';

  const parts = relPath.split(path.sep);

  if (relPath.startsWith('knowledge/')) {
    const fileName = parts[parts.length - 1].replace(/\.\w+$/, '');
    return `knowledge/${fileName}`;
  }

  if (relPath.startsWith('docs/')) {
    if (relPath.includes('engineering-rules') || relPath.includes('code-patterns')) {
      return 'engineering';
    }
    if (relPath.includes('对接文档') || relPath.includes('-api')) {
      return 'api-docs';
    }

return 'docs';
  }

  return 'unknown';
}

function toRepoRelative(absPath) {
  return path.relative(REPO_ROOT, absPath).split(path.sep).join('/');
}

module.exports = {
  REPO_ROOT,
  EXCLUDED_DIRS,
  SOURCE_GLOBS,
  shouldExcludeDir,
  getLayerForFile,
  inferModule,
  toRepoRelative,
};
```

